-- name: GetItem :one
SELECT (to_jsonb(t) - 'search_vector')::jsonb AS data FROM items t WHERE id = CAST(@id AS text)::uuid AND archived_at IS NULL;
-- name: ListItem :many
SELECT (to_jsonb(t) - 'search_vector')::jsonb AS data FROM items t WHERE (sqlc.arg(include_archived)::boolean OR archived_at IS NULL) AND to_jsonb(t) @> CAST(@filter AS jsonb) AND NOT EXISTS (SELECT 1 FROM jsonb_each(CAST(@any_of AS jsonb)) e WHERE NOT e.value @> (to_jsonb(t) -> e.key)) ORDER BY created_at, id LIMIT CAST(@page_limit AS int) OFFSET CAST(@page_offset AS int);
-- name: PutItem :one
INSERT INTO items (id, project_id, feature_id, blocked_reason, raw_text, title, body_md, progress, refs, tags, status, priority, source) VALUES (COALESCE(NULLIF(CAST(@payload AS jsonb)->>'id','')::uuid, gen_random_uuid()), NULLIF(CAST(@payload AS jsonb)->>'project_id','')::uuid, NULLIF(CAST(@payload AS jsonb)->>'feature_id','')::uuid, COALESCE(CAST(@payload AS jsonb)->>'blocked_reason', ''), COALESCE(CAST(@payload AS jsonb)->>'raw_text', ''), CAST(@payload AS jsonb)->>'title', COALESCE(CAST(@payload AS jsonb)->>'body_md', ''), COALESCE(CAST(@payload AS jsonb)->>'progress', ''), ARRAY(SELECT jsonb_array_elements_text(COALESCE(CAST(@payload AS jsonb)->'refs', '[]'::jsonb))), ARRAY(SELECT jsonb_array_elements_text(CAST(@payload AS jsonb)->'tags')), COALESCE(CAST(@payload AS jsonb)->>'status', 'inbox'), COALESCE((CAST(@payload AS jsonb)->>'priority')::integer, 0), COALESCE(CAST(@payload AS jsonb)->>'source', 'manual')) ON CONFLICT (id) DO UPDATE SET project_id = EXCLUDED.project_id, feature_id = EXCLUDED.feature_id, blocked_reason = EXCLUDED.blocked_reason, raw_text = EXCLUDED.raw_text, title = EXCLUDED.title, body_md = EXCLUDED.body_md, progress = EXCLUDED.progress, refs = EXCLUDED.refs, tags = EXCLUDED.tags, status = EXCLUDED.status, priority = EXCLUDED.priority, source = EXCLUDED.source, updated_at = now() WHERE items.archived_at IS NULL RETURNING (to_jsonb(items) - 'search_vector')::jsonb AS data;
-- name: ArchiveItem :one
UPDATE items SET archived_at = now(), updated_at = now() WHERE id = CAST(@id AS text)::uuid AND archived_at IS NULL RETURNING (to_jsonb(items) - 'search_vector')::jsonb AS data;
